/* UNO Party Arena — framework-free interactive prototype */
(() => {
  'use strict';
  const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
  const AVATARS=[['ninja-cat','แมวนินจา','#6f52ed'],['fire-dragon','มังกรไฟ','#ff5b52'],['electric-fox','จิ้งจอกสายฟ้า','#ffc72c'],['cute-ghost','ผีน้อย','#a88df7'],['space-explorer','นักสำรวจอวกาศ','#44c8f2'],['punk-dino','ไดโนพังก์','#64dc8e'],['rainbow-slime','สไลม์เรนโบว์','#ff69aa'],['mystic-wizard','จอมเวท','#824bd9'],['neon-robot','โรบอทนีออน','#3fd2d0'],['playful-pirate','โจรสลัด','#ef7b43'],['ice-wolf','หมาป่าน้ำแข็ง','#69bffc'],['space-bunny','กระต่ายอวกาศ','#f58fc4']];
  const avatar=(id,size='',turn=false)=>{const a=AVATARS.find(x=>x[0]===id)||AVATARS[0];return `<div class="avatar ${size} ${turn?'turn':''}" style="--av:${a[2]}"><svg viewBox="0 0 28 30" role="img" aria-label="${a[1]}"><path d="M5 22Q3 11 8 7L6 2l7 5 8-5-2 6q5 5 3 14Q14 30 5 22" fill="${a[2]}" stroke="#fff" stroke-width="1.2"/><path d="M7 11q7-5 14 0" fill="none" stroke="#fff" stroke-opacity=".65" stroke-width="2"/><circle cx="10.5" cy="16" r="1.5" fill="#30234f"/><circle cx="17.5" cy="16" r="1.5" fill="#30234f"/><path d="M11 21q3 2.5 6 0" fill="none" stroke="#30234f" stroke-width="1.4" stroke-linecap="round"/></svg></div>`};
  const label=c=>c.kind==='number'?c.value:{skip:'⊘',reverse:'↻',draw2:'+2',wild:'W',wild4:'+4'}[c.kind];
  const cardHTML=(c,opts={})=>`<div class="card ${opts.back?'back':c.color} ${opts.small?'small':''} ${opts.playable?'playable':''}" ${opts.id?`data-card="${c.id}"`:''} style="${opts.style||''}">${opts.back?'<div class="face"><b>UNO</b></div>':`<span class="corner">${label(c)}</span><div class="face"><b>${label(c)}</b></div><span class="corner bottom">${label(c)}</span>`}</div>`;
  const names=[['local','ChefNeko','ninja-cat',false],['b1','RoboNeon','neon-robot',true],['b2','FlameDino','fire-dragon',true],['b3','SlimeyPop','rainbow-slime',true],['b4','StarFox','electric-fox',true],['s1','Ghosty','cute-ghost',true],['s2','AstroPup','space-explorer',true]];
  let selected='ninja-cat',capacity=5,participants=[]; let game=null,botTimer=null,sound=true;
  const makeParticipants=()=>names.map((x,i)=>({id:x[0],name:i===0?$('#nickname').value:x[1],avatar:x[2],bot:x[3],role:i<5?'player':'spectator',host:i===0}));
  function show(screen){$$('.screen').forEach(x=>x.classList.toggle('active',x.dataset.screen===screen));$$('.overlay').forEach(x=>x.classList.add('hidden'));$('#topbar').classList.toggle('hidden',screen==='game');if(screen==='lobby')renderLobby();if(screen==='game')renderGame();window.scrollTo(0,0)}
  function openModal(id){$(`#modal-${id}`)?.classList.remove('hidden')}
  const closeModals=()=>$$('.overlay').forEach(x=>x.classList.add('hidden'));
  $$('[data-go]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.go)));$$('[data-modal]').forEach(b=>b.addEventListener('click',()=>openModal(b.dataset.modal)));$$('[data-close]').forEach(b=>b.addEventListener('click',closeModals));$$('.overlay').forEach(o=>o.addEventListener('click',e=>{if(e.target===o&&o.id!=='wildPicker')o.classList.add('hidden')}));
  $('#heroCast').innerHTML=avatar('ninja-cat')+avatar('fire-dragon');$('#joinCast').innerHTML=avatar('cute-ghost','lg')+'<span>⌁</span>'+avatar('space-explorer','lg');
  $('#createTableCast').innerHTML=`<div class="mini-table"><span class="mini-card">FUN<br>UNO</span></div>${['cute-ghost','fire-dragon','space-explorer','ninja-cat'].map((id,i)=>`<span class="create-seat seat-${i}">${avatar(id)}</span>`).join('')}`;
  function renderAvatars(){const a=AVATARS.find(x=>x[0]===selected);$('#avatarPreview').innerHTML=avatar(selected,'xl',true);$('#avatarTitle').textContent=a[1];$('#avatarGrid').innerHTML=AVATARS.map(x=>`<button class="${x[0]===selected?'selected':''}" data-avatar="${x[0]}" aria-label="${x[1]}">${avatar(x[0])}</button>`).join('');$$('[data-avatar]').forEach(b=>b.onclick=()=>{selected=b.dataset.avatar;renderAvatars()})}renderAvatars();
  $('#randomAvatar').onclick=()=>{selected=AVATARS[Math.floor(Math.random()*AVATARS.length)][0];renderAvatars()};$('#nickname').oninput=e=>$('#nameCount').textContent=`${e.target.value.length}/16`;
  $$('[data-step]').forEach(b=>b.onclick=()=>{capacity=Math.max(2,Math.min(10,capacity+Number(b.dataset.step)));$('#capacity').textContent=capacity});$$('[data-toggle]').forEach(b=>b.onclick=()=>b.classList.toggle('on'));
  $('#createRoom').onclick=()=>{participants=makeParticipants();participants.forEach((p,i)=>p.role=i<capacity?'player':'spectator');$('#lobbyName').textContent=$('#roomName').value||'ปาร์ตี้ของฉัน';show('lobby')};
  $('#roomCode').oninput=e=>{e.target.value=e.target.value.replace(/\D/g,'').slice(0,4);$$('#codeBoxes span').forEach((s,i)=>s.textContent=e.target.value[i]||'•');$('#joinRoom').textContent=`↪ เข้าห้อง ${e.target.value}`};$('#joinRoom').onclick=()=>{participants=makeParticipants();show('lobby')};
  function personHTML(p){return `<article class="person" data-person="${p.id}">${avatar(p.avatar)}<div class="person-info"><b>${p.name}${p.host?' 👑':''}</b><small>${p.role==='player'?'ผู้เล่น':'ผู้ชม'}${p.bot?' • BOT':''}</small></div>${!p.host?`<div class="person-actions"><button data-role="${p.id}" title="สลับบทบาท">${p.role==='player'?'◉':'🎮'}</button><button data-remove="${p.id}" title="นำออก">×</button></div>`:''}</article>`}
  function renderLobby(){if(!participants.length)participants=makeParticipants();const ps=participants.filter(p=>p.role==='player'),ss=participants.filter(p=>p.role==='spectator');$('#playerSeats').innerHTML=ps.map(personHTML).join('');$('#spectatorList').innerHTML=ss.map(personHTML).join('')||'<p class="mock-note">ยังไม่มีผู้ชม</p>';$('#seatCount').textContent=`${ps.length}/${capacity}`;$('#specCount').textContent=`${ss.length} คน`;$$('[data-role]').forEach(b=>b.onclick=()=>swapRole(b.dataset.role));$$('[data-remove]').forEach(b=>b.onclick=()=>{participants=participants.filter(p=>p.id!==b.dataset.remove);renderLobby()});}
  function swapRole(id){const p=participants.find(x=>x.id===id);if(p.role==='player'){p.role='spectator'}else{const ps=participants.filter(x=>x.role==='player');if(ps.length>=capacity){const swap=ps.find(x=>!x.host);if(swap)swap.role='spectator'}p.role='player'}renderLobby()}
  $('#addBot').onclick=()=>{const i=participants.length,a=AVATARS[i%AVATARS.length];participants.push({id:`g${Date.now()}`,name:`PartyPal${i+1}`,avatar:a[0],bot:true,role:participants.filter(p=>p.role==='player').length<capacity?'player':'spectator',host:false});renderLobby()};
  const COLORS=['red','yellow','green','blue'];
  function deck(){let d=[],id=0;for(const color of COLORS){d.push({id:`c${id++}`,color,kind:'number',value:0});for(let n=1;n<=9;n++)for(let k=0;k<2;k++)d.push({id:`c${id++}`,color,kind:'number',value:n});for(const kind of ['skip','reverse','draw2'])for(let k=0;k<2;k++)d.push({id:`c${id++}`,color,kind})}for(let i=0;i<4;i++){d.push({id:`c${id++}`,color:'wild',kind:'wild'},{id:`c${id++}`,color:'wild',kind:'wild4'})}return shuffle(d)}
  function shuffle(a){for(let i=a.length-1;i;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
  function newGame(){const ps=participants.filter(p=>p.role==='player').slice(0,10).map(p=>({...p,hand:[],uno:false})),d=deck();for(let n=0;n<7;n++)ps.forEach(p=>p.hand.push(d.pop()));let top=d.pop();while(top.color==='wild'||top.kind!=='number'){d.unshift(top);top=d.pop()}game={players:ps,draw:d,discard:[top],current:0,direction:1,color:top.color,phase:'playing',winner:null};show('game');scheduleBot()}
  $('#startGame').onclick=newGame;$('#rematch').onclick=newGame;
  function playable(c,player=game.players[game.current]){const top=game.discard.at(-1);if(c.kind==='wild4')return !player.hand.some(other=>other!==c&&other.color===game.color);return c.kind==='wild'||c.color===game.color||(c.kind==='number'&&top.kind==='number'&&c.value===top.value)||(c.kind!=='number'&&c.kind===top.kind)}
  function nextIndex(steps=1){return(game.current+game.direction*steps+game.players.length*steps)%game.players.length}
  function drawCards(index,count){const drawn=[];for(let i=0;i<count;i++){if(!game.draw.length){const top=game.discard.pop();game.draw=shuffle(game.discard);game.discard=[top]}if(game.draw.length){const card=game.draw.pop();game.players[index].hand.push(card);drawn.push(card)}}game.players[index].uno=false;return drawn}
  function advance(steps=1){game.current=nextIndex(steps)}
  function play(player,card,color){if(game.phase!=='playing'||game.players[game.current].id!==player.id)return false;if(!playable(card,player))return false;player.hand.splice(player.hand.indexOf(card),1);game.discard.push(card);if(!player.hand.length){if(card.kind==='draw2'||card.kind==='wild4')drawCards(nextIndex(),card.kind==='draw2'?2:4);finishGame(player);return true}player.uno=false;if(player.bot&&player.hand.length===1){player.uno=true;toast(`${player.name} ตะโกน UNO!`,1200)}if(card.color==='wild'){if(!color&&player.id==='local'){game.phase='color';$('#wildPicker').classList.remove('hidden');renderGame();return true}game.color=color||bestColor(player)}else game.color=card.color;applyAction(card);renderGame();scheduleBot();return true}
  function applyAction(card){if(card.kind==='reverse'){game.direction*=-1;advance(game.players.length===2?2:1)}else if(card.kind==='skip')advance(2);else if(card.kind==='draw2'||card.kind==='wild4'){const victim=nextIndex();drawCards(victim,card.kind==='draw2'?2:4);advance(2)}else advance()}
  function bestColor(p){return COLORS.sort((a,b)=>p.hand.filter(c=>c.color===b).length-p.hand.filter(c=>c.color===a).length)[0]}
  function enforceUnoPenalty(){const missed=game.players.find((p,index)=>index!==game.current&&p.hand.length===1&&!p.uno);if(!missed)return;drawCards(game.players.indexOf(missed),2);toast(`${missed.name} ไม่ได้กด UNO — จั่วเพิ่ม 2 ใบ!`,1800);renderGame()}
  function resolveDraw(player){const drawn=drawCards(game.current,1)[0];if(drawn&&playable(drawn,player)){toast(`${player.name} จั่วได้ไพ่ที่ลงได้ — ลงทันที!`,1200);play(player,drawn,drawn.color==='wild'&&player.bot?bestColor(player):null)}else{advance();renderGame();scheduleBot()}}
  function scheduleBot(){clearTimeout(botTimer);if(!game||game.phase!=='playing')return;const p=game.players[game.current];if(!p.bot)return;botTimer=setTimeout(()=>{enforceUnoPenalty();const card=p.hand.find(c=>playable(c,p));if(card)play(p,card,card.color==='wild'?bestColor(p):null);else resolveDraw(p)},1500)}
  function renderGame(){if(!game)return;const local=game.players.find(p=>p.id==='local'),current=game.players[game.current],top=game.discard.at(-1);$('#turnPill').innerHTML=`● <b>${current.name}</b> กำลังเล่น`;$('#deckCount').textContent=`${game.draw.length} ใบ`;$('#drawPile').innerHTML=cardHTML({}, {back:true});$('#discard').innerHTML=cardHTML(top);$('#currentColor').className=`color-now c-${game.color}`;const ops=game.players.filter(p=>p.id!=='local');$('#opponents').innerHTML=ops.map((p,i)=>{const angle=ops.length===1?0:-150/2+i*150/(ops.length-1),r=angle*Math.PI/180,left=50+Math.sin(r)*43,topPos=8+(1-Math.cos(r))*54;return `<article class="opponent ${current.id===p.id?'current':''}" style="left:${left}%;top:${topPos}%">${avatar(p.avatar,'',current.id===p.id)}${p.hand.length===1?'<strong class="uno-status">UNO!</strong>':''}<span class="op-label">${p.name} • ${p.hand.length} ใบ</span><div class="mini-cards">${Array.from({length:Math.min(7,p.hand.length)},()=>cardHTML({}, {back:true})).join('')}</div></article>`}).join('');
    $('#localUser').innerHTML=avatar(local.avatar,'',current.id==='local')+`<div><b>${local.name}</b><small>${current.id==='local'?'ตาคุณแล้ว!':'รออีกนิด...'}</small></div>${local.hand.length===1?`<strong class="local-uno-status ${local.uno?'declared':'pending'}">${local.uno?'UNO!':'กด UNO!'}</strong>`:''}`;$('#playerHand').innerHTML=local.hand.map((c,i)=>{const center=i-(local.hand.length-1)/2,ok=current.id==='local'&&playable(c,local);return cardHTML(c,{id:true,playable:ok,style:`--rot:${center*Math.min(7,48/local.hand.length)}deg;--lift:${Math.abs(center)*1.1}px;z-index:${i}`})}).join('');$$('[data-card]').forEach(el=>el.onclick=()=>{const c=local.hand.find(x=>x.id===el.dataset.card);if(!play(local,c)){el.classList.add('invalid');toast(c.kind==='wild4'?'ลง +4 ไม่ได้ เพราะคุณยังมีไพ่สีปัจจุบัน':'ไพ่ใบนี้ลงไม่ได้');setTimeout(()=>el.classList.remove('invalid'),400)}});$('#drawBtn').disabled=current.id!=='local'||game.phase!=='playing';$('#unoBtn').disabled=local.hand.length!==1||local.uno;$('#unoBtn').textContent=local.uno?'UNO แล้ว!':'UNO!';}
  $('#drawBtn').onclick=()=>{const p=game.players[game.current];if(p.id!=='local')return;resolveDraw(p)};$('#unoBtn').onclick=()=>{const p=game.players.find(x=>x.id==='local');if(p.hand.length===1&&!p.uno){p.uno=true;renderGame();$('#unoBurst').classList.remove('hidden');setTimeout(()=>$('#unoBurst').classList.add('hidden'),1300)}};
  $$('[data-color]').forEach(b=>b.onclick=()=>{const color=b.dataset.color,card=game.discard.at(-1),player=game.players[game.current];game.color=color;game.phase='playing';$('#wildPicker').classList.add('hidden');applyAction(card);renderGame();scheduleBot()});
  function toast(msg,duration=1500){$('#toast').textContent=msg;$('#toast').classList.remove('hidden');setTimeout(()=>$('#toast').classList.add('hidden'),duration)}
  function finishGame(player){clearTimeout(botTimer);game.winner=player;game.phase='finished';renderGame();$('#turnPill').innerHTML=`🏆 <b>${player.name}</b> ลงไพ่ใบสุดท้าย`;$('#winnerBurstName').textContent=player.name;$('#winnerBurst').classList.remove('hidden');setTimeout(()=>{$('#winnerBurst').classList.add('hidden');showResult()},2400)}
  function showResult(){const ranking=[...game.players].sort((a,b)=>a.hand.length-b.hand.length);$('#winnerName').textContent=game.winner.name;$('#winnerAvatar').innerHTML=avatar(game.winner.avatar,'xl',true);$('#ranking').innerHTML=ranking.map((p,i)=>`<div class="rank-row"><strong>${i+1}</strong>${avatar(p.avatar)}<b>${p.name}</b><small>${p.hand.length?'เหลือ '+p.hand.length+' ใบ':'ชนะ!'}</small></div>`).join('');show('result')}
  const invite=`${location.href.replace(/prototype\.html.*$/,'prototype.html')}#join-7749`;$('#inviteUrl').textContent=invite;function copy(){navigator.clipboard?.writeText(invite);toast('คัดลอกลิงก์แล้ว')}$('#copyLink').onclick=copy;$('#copyLink2').onclick=copy;$('#shareLine').onclick=()=>window.open(`https://social-plugins.line.me/lineit/share?url=${encodeURIComponent(invite)}`,'_blank');
  $('#soundBtn').onclick=()=>{sound=!sound;$('#soundBtn').textContent=sound?'🔊':'🔇';$('#soundToggle').classList.toggle('on',sound)};$('#soundToggle').onclick=()=>{$('#soundBtn').click()};
  if(location.hash==='#join-7749')show('join');
  if(location.hash==='#game-preview'){participants=makeParticipants();newGame()}
  if(location.hash==='#uno-preview'){participants=makeParticipants();newGame();game.players[0].hand=game.players[0].hand.slice(0,1);game.players[1].hand=game.players[1].hand.slice(0,1);game.players[1].uno=true;renderGame()}
  if(location.hash==='#avatar-preview')show('avatar');
  if(location.hash==='#create-preview')show('create');
  if(location.hash==='#lobby-preview'){participants=makeParticipants();show('lobby')}
})();
